-- Fighter strength rows, the same as drizzle/0057_fighter_strength_rows.sql.
-- Appended to seed.sql after libraryLevels.sql.
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-chin-up-band', 'Chin-Up (Band)', 'strength', 'back,biceps,grip', 'pull-up bar,band', 'Palms toward you, hands shoulder-width, a band under the knees or feet. Start from a dead hang, pull until the chin clears the bar, lower all the way.', NULL, 1793000000);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-chin-up-negative', 'Chin-Up (Slow Lowering)', 'strength', 'back,biceps,grip', 'pull-up bar', 'Step or jump to the top, chin over the bar, palms toward you. Lower yourself as slowly as you can, about 5 seconds, all the way to a hang.', NULL, 1793000000);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-chin-up', 'Chin-Up', 'strength', 'back,biceps,grip', 'pull-up bar', 'Palms toward you, hands shoulder-width. From a dead hang, pull the chest toward the bar until the chin clears it. Lower under control to a full hang.', NULL, 1793000000);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-dips', 'Dips', 'strength', 'triceps,chest,shoulders', 'dip bars', 'Arms straight on the bars, shoulders down. Lower until the upper arms are level with the floor, body leaning a little forward, then press back up.', NULL, 1793000000);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-close-grip-bench', 'Close-Grip Bench Press', 'strength', 'triceps,chest,shoulders', 'barbell,bench', 'Hands just inside shoulder-width. Elbows tucked close to the body, bar to the lower chest, press straight up.', NULL, 1793000000);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-copenhagen-plank', 'Copenhagen Plank', 'core', 'adductors,obliques', 'bench,bodyweight', 'Side plank on one forearm, the top leg on a bench (knee on it to start, foot later), the bottom leg tucked under. Lift the hips into a straight line and hold.', NULL, 1793000000);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-nordic-curl', 'Nordic Curl', 'core', 'hamstrings', 'bodyweight', 'Kneel with the heels held down (a partner, a pad or a loaded bar). Hips straight, lower the body forward as slowly as you can, catch with the hands, push back up.', NULL, 1793000000);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-bent-knee-calf-raise', 'Bent-Knee Calf Raise', 'strength', 'calves,soleus,achilles', 'dumbbell,bench', 'Seated, knees bent at 90 degrees, a dumbbell across the knees, balls of the feet on a plate. Full stretch at the bottom, rise high, lower for 2-3 seconds.', NULL, 1793000000);
UPDATE exercises SET tips = 'The band takes the hardest part. | Thinner band as you get stronger. | Reps only, never added weight.', coach_hint = 'The first rung of the chin-up ladder: band, then slow lowering, then full.' WHERE id = 'ex-chin-up-band';
UPDATE exercises SET tips = 'About 5 seconds down. | Reset at the top each rep.', coach_hint = 'The second rung: the slow lowering builds the strength for full chin-ups.' WHERE id = 'ex-chin-up-negative';
UPDATE exercises SET tips = 'Pull with the back, not just the arms. | Full hang at the bottom.', coach_hint = 'Back, biceps and grip for the clinch. The coach adds reps, never weight.' WHERE id = 'ex-chin-up';
UPDATE exercises SET tips = 'Stop short if the front of the shoulder pinches. | Feet behind you, not in front.', coach_hint = 'Pressing strength for the arms. The close-grip press stands in when dips don''t suit the shoulders.' WHERE id = 'ex-dips';
UPDATE exercises SET tips = 'Wrists straight over the elbows. | Not so close the wrists bend.', coach_hint = 'The triceps press of the arm block while the shoulders rebuild.' WHERE id = 'ex-close-grip-bench';
UPDATE exercises SET tips = 'Knee on the bench first, the foot when that is easy. | Hold the time each side.', coach_hint = 'Groin insurance for kicks and teeps (Harøy 2019).' WHERE id = 'ex-copenhagen-plank';
UPDATE exercises SET tips = 'Go only as slow and as far as you control. | Hands catch you every rep.', coach_hint = 'Hamstring insurance for hard runs and kicks (van der Horst 2015).' WHERE id = 'ex-nordic-curl';
UPDATE exercises SET tips = 'Knees bent works the soleus, the calf that takes running. | Same slow lowering as the single-leg raise.', coach_hint = 'Calf strength for running and footwork, the bent-knee half.' WHERE id = 'ex-bent-knee-calf-raise';
UPDATE exercises SET equipment = 'dumbbell' WHERE id = 'ex-single-leg-calf-raise';
